def transform(grid):
    separator = 3
    sep_rows = [i for i, row in enumerate(grid) if all(x == separator for x in row)]
    sep_cols = [j for j in range(len(grid[0])) if all(grid[i][j] == separator for i in range(len(grid)))]
    row_bounds = [-1] + sep_rows + [len(grid)]
    col_bounds = [-1] + sep_cols + [len(grid[0])]

    special = next(v for row in grid for v in row if v not in (separator, 4))
    result = []
    for r0, r1 in zip(row_bounds, row_bounds[1:]):
        out_row = []
        for c0, c1 in zip(col_bounds, col_bounds[1:]):
            count = sum(grid[i][j] == special
                        for i in range(r0 + 1, r1)
                        for j in range(c0 + 1, c1))
            out_row.append(1 if count >= 2 else 5)
        result.append(out_row)
    return result
